/* @lc app=leetcode id=3573 lang=kotlin */ class Solution { fun maximumProfit(prices: IntArray, k: Int): Long = Long.MIN_VALUE.div(4).let { NEG -> prices.fold(Triple(LongArray(k + 1) { if (it == 0) 0L else NEG }, LongArray(k + 1) { NEG }, LongArray(k + 1) { NEG })) { (f, g, h), p -> Triple(LongArray(k + 1) { j -> maxOf(f[j], if (j > 0) maxOf(g[j - 1] + p, h[j - 1] - p) else NEG) }, LongArray(k + 1) { j -> maxOf(g[j], f[j] - p) }, LongArray(k + 1) { j -> maxOf(h[j], f[j] + p) }) }.first.max() } }